function validate([intervals, toBeRemoved]) {
  const ok = pair => Array.isArray(pair) && pair.length === 2 && pair.every(Number.isInteger) && pair[0] >= -1e9 && pair[1] <= 1e9 && pair[0] < pair[1];
  if (!Array.isArray(intervals) || intervals.length < 1 || intervals.length > 10000) return 'intervals needs 1 to 10^4 pairs.';
  if (!intervals.every(ok)) return 'Each interval is [a, b] with -10^9 <= a < b <= 10^9.';
  if (!ok(toBeRemoved)) return 'toBeRemoved is [a, b] with -10^9 <= a < b <= 10^9.';
  for (let i = 1; i < intervals.length; i++) {
    if (intervals[i - 1][1] > intervals[i][0]) return 'intervals must be sorted and must not overlap.';
  }
  return null;
}

