function removeInterval(intervals, toBeRemoved) {
  // Cut the line at every endpoint; each elementary piece is wholly in or out of every range.
  const points = [...new Set([...intervals.flat(), ...toBeRemoved])].sort((a, b) => a - b);
  const pieces = [];
  for (let k = 0; k + 1 < points.length; k++) {
    const lo = points[k], hi = points[k + 1];
    const owner = intervals.findIndex(([a, b]) => a <= lo && hi <= b);
    const removed = toBeRemoved[0] <= lo && hi <= toBeRemoved[1];
    if (owner < 0 || removed) continue;
    const last = pieces[pieces.length - 1];
    if (last && last.owner === owner && last.hi === lo) last.hi = hi;
    else pieces.push({ owner, lo, hi });
  }
  return pieces.map(p => [p.lo, p.hi]);
}

