function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 6);
  const maxGap = large ? 400000 : 3;
  const maxLen = large ? 400000 : 4;
  const intervals = [];
  let cursor = large ? -1000000000 + Math.floor(rand() * 1000) : -12 + Math.floor(rand() * 6);
  for (let i = 0; i < n; i++) {
    // A gap of 0 lets neighbours touch, which the problem allows.
    const gap = rand() < 0.25 ? 0 : Math.floor(rand() * (maxGap + 1));
    const start = i === 0 ? cursor : cursor + gap;
    const end = start + 1 + Math.floor(rand() * maxLen);
    intervals.push([start, end]);
    cursor = end;
  }
  const low = intervals[0][0] - (large ? 1000 : 3);
  const high = intervals[n - 1][1] + (large ? 1000 : 3);
  const pick = () => low + Math.floor(rand() * (high - low + 1));
  let x = pick();
  let y = pick();
  if (rand() < 0.3) {
    // Snap to existing endpoints so boundary cases come up often.
    const ends = intervals.flat();
    x = ends[Math.floor(rand() * ends.length)];
    y = ends[Math.floor(rand() * ends.length)];
  }
  if (x > y) [x, y] = [y, x];
  if (x === y) y = x + 1;
  return [intervals, [x, y]];
}
